function toast(message,error=false){$('#toast').textContent=message;$('#toast').classList.toggle('error',error);$('#toast').classList.add('visible');toastUntil=performance.now()+6500;}
function sound(freq=440,duration=.14,type='sine'){if(muted||!audio)return;const o=audio.createOscillator(),v=audio.createGain();o.frequency.value=freq;o.type=type;v.gain.setValueAtTime(.0001,audio.currentTime);v.gain.exponentialRampToValueAtTime(.07,audio.currentTime+.02);v.gain.exponentialRampToValueAtTime(.0001,audio.currentTime+duration);o.connect(v);v.connect(audio.destination);o.start();o.stop(audio.currentTime+duration);}
$('#sound').addEventListener('click',async()=>{muted=!muted;if(!muted){audio??=new AudioContext();await audio.resume();sound(523,.3);setTimeout(()=>sound(659,.35),130);}$('#sound').innerHTML=`<span>&#9835;</span> Sound ${muted?'off':'on'}`;$('#sound').setAttribute('aria-pressed',String(!muted));});
