const guide=()=>show(`<span class="eyebrow">A LITTLE GUIDE TO YESTERDAY</span><h2 class="modal-title">Your past is<br>your superpower.</h2><p class="modal-desc">You have 90 seconds in each loop. When time resets, a glowing echo repeats the route you just walked, then stays where you ended. Leave your echoes where your next self needs help.</p><ol class="guide-list"><li><strong>Find your ticket.</strong> Walk to the amber kiosk on the left. Press E. Your ticket survives every reset.</li><li><strong>Leave a helper at the gate.</strong> Stand in the centre of the amber pad marked I, then press R. On the next loop, your echo walks there and holds the canal gate open.</li><li><strong>Make it across.</strong> Wait for the gate to light up. Cross using the bridge in the centre of the canal. Walk to the blue pad II and rewind there.</li><li><strong>Catch the last tram.</strong> On your third loop, your two echoes handle the gate and power. Walk up to the tram and press E before the last five seconds.</li></ol><div class="modal-note">WASD / arrows move around the map. Click the ground to find a route. E interacts. R rewinds. Escape pauses solo play. On a phone, tap to walk or use the direction buttons. Keep a pad lit by standing in its centre. Up to 12 echoes are kept; the oldest fades when the limit is reached.</div><div class="modal-actions"><button class="button primary" id="guide-close">I've got this ↗</button></div>`);
function team(){show(`<span class="eyebrow">FOUR MINDS. ONE TOMORROW.</span><h2 class="modal-title">The people<br>behind the echoes.</h2><p class="modal-desc">A Web Programming midterm project about teamwork—even when your teammate is yesterday's you.</p><div class="team-grid">${CHARACTERS.map((p,i)=>`<div class="team-card"><span class="team-avatar" style="background:${p.color}">${p.name.slice(0,2)}</span><strong>${p.name}</strong><small>${['Game rules & time echoes','World illustration & interface','Interactions & multiplayer','Testing & presentation'][i]} · proposed responsibility</small></div>`).join('')}</div><div class="modal-note">Original procedural canvas artwork, deterministic replay, responsive controls, saved solo progress, and an optional Node server for 1–4 players on the same server.</div>`);}
document.querySelectorAll('[data-modal]').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.modal==='guide')guide();else if(b.dataset.modal==='team')team();else show(`<span class="eyebrow">BUILT FOR THE BROWSER</span><h2 class="modal-title">A small world.<br>A lot of possibility.</h2><p class="modal-desc">ECHO — The Last Tram is an original time-loop puzzle. The city is drawn entirely with Canvas 2D: buildings, reflections, rain, tram, people, and light. No downloaded artwork or game engine is needed.</p><p class="modal-desc">Solo mode runs locally in your browser. Optional cooperative rooms run on the included Node server. Music is synthesized in your browser when you turn sound on. Inspired by the feeling of missing a train and wishing for one more chance.</p><div class="modal-note">Created for Sudip, Sondor, Eric, and Abinash. Fictional city and story. Version 1.0 · Chapter 01.</div>`);}));
