$('#start').addEventListener('click',()=>{game=createGame([{...CHARACTERS[selectedCharacter],id:'solo'}]);game.started=true;replayTime=null;overview=false;cameraState=null;markPlaying();toast('Welcome to Kisaragi. Find the glowing ticket kiosk—click the ground to walk, then press E.');sound(392,.4);});
$('#continue').addEventListener('click',()=>{try{game=importSave(localStorage.getItem(saveKey));game.started=true;endingShown=false;markPlaying();toast('Welcome back. Your memories and echoes were waiting.');}catch{toast('That save could not be opened. Start a fresh journey.',true);}});
