function pause(){if(!game.started||game.won)return;if(network){toast('The shared city keeps moving. Leave a room from the team menu.');return;}game.paused=!game.paused;keys.clear();$('#pause').textContent=game.paused?'▶':'Ⅱ';$('#pause').setAttribute('aria-label',game.paused?'Resume game':'Pause game');if(game.paused)toast('A little breathing room. Press Escape or the play button to resume.');last=performance.now();}
