window.addEventListener('keydown',e=>{if(modal.open||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' ','w','a','s','d','e','r','m','Escape'].includes(e.key))e.preventDefault();if(e.repeat)return;keys.add(e.key.toLowerCase());if(e.key.toLowerCase()==='r')doRewind();if(e.key.toLowerCase()==='e')doInteract();if(e.key.toLowerCase()==='m')toggleOverview();if(e.key==='Escape')pause();});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>keys.clear());document.addEventListener('visibilitychange',()=>{keys.clear();if(!network&&game.started&&!game.won){if(document.hidden&&!game.paused){game.paused=true;hiddenPause=true;}else if(!document.hidden&&hiddenPause){game.paused=false;hiddenPause=false;last=performance.now();}}});
document.querySelectorAll('[data-direction]').forEach(b=>{const key={up:'w',down:'s',left:'a',right:'d'}[b.dataset.direction];b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(key);});for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,()=>keys.delete(key));});
// A small breadth-first pathfinder routes clicks around buildings and across an open bridge.
function findRoute(from,to){const step=.4,cols=Math.ceil(WORLD.w/.4)+1,rows=Math.ceil(WORLD.h/.4)+1,key=(x,y)=>y*cols+x;const start={x:Math.round(from.x/step),y:Math.round(from.y/step)},goal={x:Math.round(to.x/step),y:Math.round(to.y/step)};const queue=[start],seen=new Map([[key(start.x,start.y),null]]);let end=null;for(let i=0;i<queue.length;i++){const p=queue[i];if(Math.hypot(p.x-goal.x,p.y-goal.y)<1.2){end=p;break;}for(const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]]){const x=p.x+dx,y=p.y+dy,k=key(x,y);if(x<0||y<0||x>=cols||y>=rows||seen.has(k)||blocked(x*step,y*step,game.gateOpen))continue;seen.set(k,p);queue.push({x,y});}}if(!end)return [];const path=[];while(end){path.unshift({x:end.x*step,y:end.y*step});end=seen.get(key(end.x,end.y));}return path.slice(1);}
canvas.addEventListener('pointerdown',e=>{if(!game.started||game.paused||game.won)return;const r=canvas.getBoundingClientRect(),cam=cameraForGame();let sx=(e.clientX-r.left)*1200/r.width,sy=(e.clientY-r.top)*760/r.height;if(cam){const scene=screenToScene(sx,sy,cam);sx=scene.x;sy=scene.y;}const q=draw.pick((e.clientX-r.left)*1200/r.width,(e.clientY-r.top)*760/r.height),p=game.players.find(p=>p.id===myId);if(!q){toast('Tap the street below the horizon to walk there.');return;}if(!p)return;route=findRoute(p,q);if(!route.length)toast('No clear path there yet. The canal bridge opens while the amber pad is held.');canvas.focus({preventScroll:true});});
