modal.addEventListener('click',e=>{if(e.target.id==='cancel-reset')close();if(e.target.id==='confirm-reset'){if(network)leaveRoom();try{localStorage.removeItem(saveKey);}catch{}game=createGame();saved=false;route=[];endingShown=false;replayTime=null;overview=false;cameraState=null;$('#continue').hidden=true;$('#start-card').hidden=false;$('#rewind').disabled=true;$('#pause').hidden=true;document.body.classList.remove('playing');close();}});
function ending(){endingShown=true;persist();sound(523,.7);setTimeout(()=>sound(659,.7),180);setTimeout(()=>sound(784,1),360);show(`<span class="eyebrow">CHAPTER 01 / TOMORROW, AT LAST</span><div class="success-emblem">✧</div><h2 class="modal-title" style="text-align:center">You were never<br>doing this alone.</h2><p class="modal-desc">The doors close softly. The conductor turns around. It is you—older, smiling, and finally on time.</p><p class="memory">“I knew you'd make it. I remember helping.”</p><div class="ending-stat"><div><b>${game.loop}</b><span>LOOPS LIVED</span></div><div><b>${game.echoes.length}</b><span>PAST SELVES</span></div><div><b>${Math.floor(game.time)}s</b><span>FINAL LOOP</span></div></div><div class="modal-actions"><button class="button primary" id="download-replay">Save your journey ↗</button><button class="button secondary" id="watch-replay">Watch your echoes</button></div><p class="modal-desc">Chapter complete. Try again with fewer loops, or bring your team into the same city.</p>`);}
modal.addEventListener('click',e=>{if(e.target.id==='watch-replay'){close();toast('Your echoes are shown in the city. Revisit their timeline with the replay slider.');showReplay();}if(e.target.id==='download-replay'){const blob=new Blob([JSON.stringify({...game,recording:[]},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='echo-your-journey.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}});
function showReplay(){show(`<span class="eyebrow">THE THINGS YOU MADE POSSIBLE</span><h2 class="modal-title">Yesterday, together.</h2><p class="modal-desc">Close this panel after selecting a moment to see where each echo was in the final loop. Your completed game is preserved.</p><label class="modal-desc">Replay time <input id="replay-time" type="range" min="0" max="90" step="0.1" value="${game.time}" style="width:100%;accent-color:#dce99a"><output id="replay-value">${Math.floor(game.time)} seconds</output></label><div class="modal-actions"><button id="replay-view" class="button primary">See this moment ↗</button></div>`);}
modal.addEventListener('input',e=>{if(e.target.id==='replay-time')$('#replay-value').textContent=e.target.value+' seconds';});modal.addEventListener('click',e=>{if(e.target.id==='replay-view'){const time=Number($('#replay-time').value);close();replayTime=time;overview=true;$('#overview').setAttribute('aria-pressed','true');$('#zoom-label').textContent='CITY OVERVIEW';}});let replayTime=null;
// Cooperative rooms are available when the optional Node server is running.
async function request(path,body){const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const j=await r.json();if(!r.ok)throw new Error(j.error||'The room server could not complete that request.');return j;}
function coop(){if(!apiAvailable){show(`<span class="eyebrow">YOUR PEOPLE. THE SAME MOMENT.</span><h2 class="modal-title">Four friends.<br>One little city.</h2><p class="modal-desc">This hosted edition runs solo in your browser. For live cooperative play, launch the included ECHO Node server on one laptop. Everyone opens that laptop's address, then creates or joins a room here.</p><div class="modal-note">Run <code>npm start</code> in the project folder. Open <code>http://localhost:3001</code> on the host. Teammates use <code>http://HOST-IP:3001</code> on the same private network. No account or database subscription is needed. The host starts and rewinds; everyone can move and interact. Rooms last while the server runs.</div><p class="modal-desc">In co-op, friends can hold the two pads immediately—or make echoes together. A publicly hosted Node server also supports remote players.</p>`);return;}show(`<span class="eyebrow">BETTER TOGETHER</span><h2 class="modal-title">Bring your people<br>into the loop.</h2><form id="room-form" class="room-form"><label>Your character<select name="character">${CHARACTERS.map((p,i)=>`<option value="${i}">${p.name}</option>`).join('')}</select></label><label>Room code (leave blank to create)<input name="code" placeholder="e.g. A4B8C2" maxlength="6" autocomplete="off"></label><p id="room-error" class="room-error" role="alert"></p><button class="button primary" type="submit">Create or join a room ↗</button></form>${network?'<div class="modal-actions"><button id="leave-room" class="button secondary">Leave this room</button></div>':''}<p class="modal-desc">Up to four people. One server. The host controls start and rewind.</p>`);}
$('#coop-button').addEventListener('click',coop);
modal.addEventListener('submit',async e=>{if(e.target.id!=='room-form')return;e.preventDefault();const f=new FormData(e.target),code=String(f.get('code')||'').trim().toUpperCase(),character=Number(f.get('character'));try{const data=await request(code?'/api/join':'/api/create',{code,character});connectRoom(data);close();showLobby();}catch(err){$('#room-error').textContent=err.message;}});
function connectRoom(data){if(network)network.source.close();network={...data,source:new EventSource(`/api/room/${data.code}/events?key=${encodeURIComponent(data.key)}`)};myId=data.playerId;route=[];network.source.onmessage=e=>{const state=JSON.parse(e.data),oldLoop=game.loop;game=state;if(game.loop!==oldLoop){route=[];flash();}if(game.started)markPlaying();$('#session-label').textContent='ROOM '+network.code+' · '+game.players.length+'/4';if(modal.open&&$('#lobby-players'))renderLobby();};network.source.onerror=()=>toast('Room connection interrupted. Reconnecting…',true);}
async function netAction(type,data={}){if(!network)return;try{await request(`/api/room/${network.code}/action`,{key:network.key,type,data});}catch(e){toast(e.message,true);}}
function showLobby(){show(`<span class="eyebrow">A SHARED TOMORROW</span><h2 class="modal-title">Room ${network.code}</h2><p class="modal-desc">Share this six-character code with friends on the same server.</p><div id="lobby-players" class="room-players"></div><div class="modal-actions"><button id="start-room" class="button primary">Start the shared loop ↗</button><button id="leave-room" class="button secondary">Leave room</button></div><p class="modal-desc">The host can start with 1–4 players. All players can help hold pads and catch the tram. Rewinds record everybody's actions.</p>`);renderLobby();}
function renderLobby(){if(!$('#lobby-players'))return;$('#lobby-players').replaceChildren(...game.players.map(p=>{const el=document.createElement('span');el.textContent=p.name;el.style.color=p.color;return el;}));$('#start-room').disabled=game.host!==myId;}
function leaveRoom(){if(network){netAction('leave');network.source.close();network=null;}myId='solo';game=createGame();route=[];$('#session-label').textContent='SOLO EXPLORATION';$('#start-card').hidden=false;document.body.classList.remove('playing');$('#rewind').disabled=true;$('#pause').hidden=true;endingShown=false;}
modal.addEventListener('click',e=>{if(e.target.id==='start-room'){netAction('start');close();}if(e.target.id==='leave-room'){leaveRoom();close();}});
function input(){// Screen-space arrows map to the angled isometric streets.
 const right=Number(keys.has('d')||keys.has('arrowright'))-Number(keys.has('a')||keys.has('arrowleft')),down=Number(keys.has('s')||keys.has('arrowdown'))-Number(keys.has('w')||keys.has('arrowup'));return {dx:right+down,dy:down-right};}
