function destination(){const gate=game.echoes.some(e=>dist(e.endPosition||e.frames.at(-1),WORLD.gatePad)<.7),power=game.echoes.some(e=>dist(e.endPosition||e.frames.at(-1),WORLD.powerPad)<.7);if(!game.ticket)return {...WORLD.ticket,name:'TICKET KIOSK',action:'Find your ticket · E to collect'};if(!gate&&!network)return {...WORLD.gatePad,name:'GATE PAD',action:'Stand on amber I · R to leave an echo'};if(!power&&!game.power)return {...WORLD.powerPad,name:'POWER PAD',action:'Stand on blue II · R to leave an echo'};return {...WORLD.tram,name:'LAST TRAM',action:'Board the tram · E to interact'};}
function updatePerspective(){const p=game.players.find(p=>p.id===myId)||game.players[0],goal=destination();if(!p)return;$('#location-name').textContent=p.x>17?(p.y>12?'TOMORROW LOOKOUT':'LANTERN GARDEN'):p.y>14?'THE WAITING CLOCK':p.x>8?'TOMORROW STATION':'YESTERDAY LANE';$('#location-sub').textContent=game.started?goal.action:'Explore a city that remembers you.';const marker=$('#objective-marker'),screen=draw.project(goal.x,goal.y,1.6)||{x:600,y:100};marker.hidden=!game.started||game.won||overview;if(!marker.hidden){const x=Math.max(100,Math.min(1100,screen.x)),y=Math.max(130,Math.min(610,screen.y));marker.style.left=(x/12)+'%';marker.style.top=(y/7.6)+'%';marker.textContent='◇ '+goal.name+' · '+Math.round(dist(p,goal)*4)+'m';marker.classList.toggle('offscreen',x!==screen.x||y!==screen.y);}
 drawMinimap(p,goal);}
const mini=$('#minimap'),mc=mini.getContext('2d');
function drawMinimap(player,goal){mc.clearRect(0,0,216,150);const corners=[iso(0,0),iso(WORLD.w,0),iso(WORLD.w,WORLD.h),iso(0,WORLD.h)],minX=Math.min(...corners.map(p=>p.x)),maxX=Math.max(...corners.map(p=>p.x)),minY=Math.min(...corners.map(p=>p.y)),maxY=Math.max(...corners.map(p=>p.y)),scale=Math.min(188/(maxX-minX),112/(maxY-minY)),point=(x,y)=>{const q=iso(x,y);return {x:14+(q.x-minX)*scale,y:22+(q.y-minY)*scale};};mc.beginPath();corners.forEach((q,i)=>{const x=14+(q.x-minX)*scale,y=22+(q.y-minY)*scale;i?mc.lineTo(x,y):mc.moveTo(x,y);});mc.closePath();mc.fillStyle='#355358';mc.fill();mc.strokeStyle='#8bac9566';mc.stroke();const line=(x,y,x2,y2,color)=>{const a=point(x,y),b=point(x2,y2);mc.beginPath();mc.moveTo(a.x,a.y);mc.lineTo(b.x,b.y);mc.strokeStyle=color;mc.lineWidth=2;mc.stroke();};line(8,0,8,WORLD.h,'#80b6c099');line(7,8,9,8,game.gateOpen?'#dce99a':'#e9aa8e');for(const b of BUILDINGS){const q=point(b.x+b.w/2,b.y+b.h/2);mc.fillStyle='#a7bbb477';mc.fillRect(q.x-3,q.y-2,6,4);}const dot=(a,r,color)=>{const q=point(a.x,a.y);mc.beginPath();mc.arc(q.x,q.y,r,0,Math.PI*2);mc.fillStyle=color;mc.fill();};for(const e of game.echoes){const a=echoAt(e,game.time);if(a)dot(a,2,'#91d5d1');}dot(goal,3,'#e8ba82');dot(player,3.5,'#e5f18c');mc.fillStyle='#a0b5ad';mc.font='7px Segoe UI';mc.textAlign='left';mc.fillText('KISARAGI / YOUR DISTRICT',12,13);mc.fillStyle='#e5f18c';mc.fillText('YOU',12,143);mc.fillStyle='#91d5d1';mc.fillText('ECHOES',55,143);mc.fillStyle='#e8ba82';mc.fillText('DESTINATION',117,143);}
let lastLoop=1;
function frame(now){const dt=Math.min(.05,(now-last)/1000);last=now;const p=game.players.find(p=>p.id===myId),i=input();if(p&&game.started&&!game.paused){if(i.dx||i.dy)route=[];while(route.length&&dist(p,route[0])<.2)route.shift();if(route.length)p.target=route[0];if(network){if(now-lastSend>90){lastSend=now;netAction('input',{...i,target:route[0]||null});}}else tick(game,dt,{[myId]:i});}if(game.loop!==lastLoop){lastLoop=game.loop;if(!network)flash();route=[];}cameraState=smoothCamera(cameraState,targetCamera(),dt,reduceMotion);draw(replayTime!==null?{...game,time:replayTime}:game,now/1000,myId,route,cameraForGame(),appearance,overview,cameraZoom);updateHud();updatePerspective();updateCreativeHud();if(game.message&&game.event!==lastEvent){lastEvent=game.event;toast(game.message);}if(now>toastUntil)$('#toast').classList.remove('visible');if(game.won&&!endingShown)ending();if(now-lastSave>5000){lastSave=now;persist();}requestAnimationFrame(frame);}
let hudStamp='';function updateHud(){const left=Math.max(0,Math.ceil(90-game.time));$('#timer').textContent=`${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`;$('#timer-fill').style.width=(left/90*100)+'%';$('.world-clock').classList.toggle('urgent',left<15);const gateEcho=game.echoes.some(e=>{const a=e.endPosition||e.frames.at(-1);return dist(a,WORLD.gatePad)<.7;}),powerEcho=game.echoes.some(e=>dist(e.endPosition||e.frames.at(-1),WORLD.powerPad)<.7);const stamp=[game.loop,game.ticket,gateEcho,powerEcho,game.echoes.length,game.memories.length,game.won].join('|');if(stamp!==hudStamp){hudStamp=stamp;$('#world-loop').textContent='LOOP '+String(game.loop).padStart(2,'0');$('#echo-count').textContent=game.echoes.length?`${game.echoes.length} ${game.echoes.length===1?'ECHO IS':'ECHOES ARE'} WALKING WITH YOU`:'NO ECHOES. YET.';$('#echo-sub').textContent=game.echoes.length?'Your past selves remember the way.':'Every rewind leaves a little of you behind.';$('#echo-dots').replaceChildren(...game.echoes.slice(-4).map(e=>{const el=document.createElement('span');el.className='echo-pill';el.textContent='◎ LOOP '+String(e.loop).padStart(2,'0');el.title=e.name+' from loop '+e.loop;return el;}));$('#memory-count').textContent=game.memories.length;for(const [sel,done,current] of [['#mission-ticket',game.ticket,!game.ticket],['#mission-gate',gateEcho,game.ticket&&!gateEcho],['#mission-tram',game.won,gateEcho&&!game.won]]){$(sel).classList.toggle('done',done);$(sel).classList.toggle('current',current);}$('#conductor').textContent=game.won?'“I knew you’d make it. I remember helping.”':powerEcho?'“They will hold the city open. Go catch your tomorrow.”':gateEcho?'“See? You already knew someone who could help.”':'“You don’t need more time. Just a little help from yourself.”';}
 const p=game.players.find(p=>p.id===myId);let hint='';if(p&&game.started&&!game.won&&!game.paused){if(dist(p,WORLD.ticket)<1.2)hint=game.ticket?'Your ticket remembers.':'Collect your ticket';else if(dist(p,WORLD.gatePad)<.8)hint='R · Leave an echo holding this gate';else if(dist(p,WORLD.powerPad)<.8)hint='R · Leave an echo powering the tram';else if(dist(p,WORLD.tram)<1.6)hint=game.power?'Board the last tram':'The tram needs power';else{const place=LANDMARKS.find(l=>dist(p,l)<1.3);if(place)hint='Remember '+place.name;}}$('#world-hint').hidden=!hint;$('#hint-text').textContent=hint;$('#hint-key').textContent=hint.startsWith('R')?'R':'E';}
window.addEventListener('beforeunload',persist);requestAnimationFrame(frame);

// Appearance stays browser-local and never changes the shared game rules.
function applyAppearance(){document.body.dataset.theme=appearance.theme;document.body.classList.toggle('calm-mode',!appearance.motion);for(const b of document.querySelectorAll('[data-theme-choice]'))b.setAttribute('aria-pressed',String(b.dataset.themeChoice===appearance.theme));$('#weather-button').innerHTML='<span>&#9730;</span>Rain '+(appearance.weather?'on':'off');$('#weather-button').setAttribute('aria-pressed',String(appearance.weather));$('#motion-button').innerHTML='<span>&#10038;</span>Motion '+(appearance.motion?'on':'off');$('#motion-button').setAttribute('aria-pressed',String(appearance.motion));try{localStorage.setItem('echo-appearance-v1',JSON.stringify(appearance));}catch{}}
document.querySelectorAll('[data-theme-choice]').forEach(b=>b.addEventListener('click',()=>{appearance.theme=b.dataset.themeChoice;applyAppearance();sound(660,.2);}));
document.querySelectorAll('[data-character]').forEach(b=>b.addEventListener('click',()=>{if(game.started){toast('Choose a character before starting a fresh solo journey.');return;}selectedCharacter=Number(b.dataset.character);for(const el of document.querySelectorAll('[data-character]'))el.setAttribute('aria-pressed',String(el===b));game.players[0]={...game.players[0],...CHARACTERS[selectedCharacter]};toast(CHARACTERS[selectedCharacter].name+' is ready for tomorrow.');}));
$('#weather-button').addEventListener('click',()=>{appearance.weather=!appearance.weather;applyAppearance();});
$('#motion-button').addEventListener('click',()=>{appearance.motion=!appearance.motion;applyAppearance();});
$('#postcard-button').addEventListener('click',()=>{const card=document.createElement('canvas');card.width=1200;card.height=850;const ctx=card.getContext('2d');ctx.fillStyle=themeFor(appearance.theme).sky[1];ctx.fillRect(0,0,1200,850);ctx.drawImage(canvas,0,0,1200,760);ctx.fillStyle=themeFor(appearance.theme).accent;ctx.font='24px Georgia';ctx.fillText('ECHO / A postcard from yesterday',35,805);ctx.fillStyle='#c0c1d4';ctx.font='13px Segoe UI';ctx.fillText(themeFor(appearance.theme).name+'  |  LOOP '+game.loop+'  |  KISARAGI STATION',35,830);card.toBlob(blob=>{if(!blob){toast('Could not save this postcard. Try again.',true);return;}const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='echo-'+appearance.theme+'-postcard.png';link.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('A little piece of yesterday, saved.');},'image/png');});
$('#badges-button').addEventListener('click',()=>{const badges=badgesFor(game);show('<span class="eyebrow">SMALL MOMENTS. REAL MILESTONES.</span><h2 class="modal-title">Your collection<br>of almost impossible.</h2><div class="badges-grid">'+badges.map(b=>'<article class="badge-card '+(b.earned?'earned':'')+'"><span>'+(b.earned?'&#10022;':'&#9671;')+'</span><strong>'+b.name+'</strong><p>'+b.detail+'</p><small>'+(b.earned?'UNLOCKED':'KEEP EXPLORING')+'</small></article>').join('')+'</div>');});
let creativeStamp='',previousLights=0;
function updateCreativeHud(){const lights=game.shards||[],badges=badgesFor(game),stamp=[lights.join(','),game.loop,game.echoes.length,game.ticket,game.won].join('|');if(stamp!==creativeStamp){creativeStamp=stamp;$('#light-count').textContent=lights.length+' / 5';$('#badge-count').textContent=badges.filter(b=>b.earned).length+' / 5';$('#light-slots').replaceChildren(...SHARDS.map(s=>{const el=document.createElement('i');el.className=lights.includes(s.id)?'collected':'';el.title=lights.includes(s.id)?'Memory collected':'Memory waiting';return el;}));if(lights.length>previousLights){$('.discovery-progress').classList.remove('discovery-pop');void $('.discovery-progress').offsetWidth;$('.discovery-progress').classList.add('discovery-pop');sound(880,.3);setTimeout(()=>sound(1108,.25),100);}previousLights=lights.length;const tracks=$('#timeline-tracks');tracks.replaceChildren();if(!game.echoes.length){const p=document.createElement('p');p.textContent='Your first rewind starts the story here.';tracks.append(p);}for(const e of game.echoes.slice(-6)){const row=document.createElement('div');row.className='timeline-track';const name=document.createElement('span');name.textContent='LOOP '+String(e.loop).padStart(2,'0')+' / '+e.name;const rail=document.createElement('div');rail.className='timeline-rail';const bar=document.createElement('i');bar.style.width=Math.min(100,((e.endPosition?.t||e.frames.at(-1).t)/90)*100)+'%';const cursor=document.createElement('b');cursor.className='timeline-cursor';rail.append(bar,cursor);const tag=document.createElement('small');tag.textContent='ECHO';row.append(name,rail,tag);tracks.append(row);}}for(const cursor of document.querySelectorAll('.timeline-cursor'))cursor.style.left=(game.time/90*100)+'%';}
applyAppearance();
